def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply_operator():
        op = operators.pop()

        if op == "~":
            values[-1] = -values[-1]
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ArithmeticError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ArithmeticError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            values.append(quotient if op == "/" else a - b * quotient)

    try:
        i = 0
        expecting_operand = True

        while i < len(expr):
            ch = expr[i]

            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                number = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    number = number * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(number)
                expecting_operand = False
            elif ch == "(":
                operators.append(ch)
                expecting_operand = True
                i += 1
            elif ch == ")":
                while operators[-1] != "(":
                    apply_operator()
                operators.pop()
                expecting_operand = False
                i += 1
            elif ch == "-" and expecting_operand:
                operators.append("~")
                i += 1
            else:
                while (
                    operators
                    and operators[-1] != "("
                    and (
                        precedence[operators[-1]] > precedence[ch]
                        or (
                            precedence[operators[-1]] == precedence[ch]
                            and ch != "^"
                        )
                    )
                ):
                    apply_operator()
                operators.append(ch)
                expecting_operand = True
                i += 1

        while operators:
            apply_operator()

        return values[0]
    except ArithmeticError:
        return "error"
